//! Formatting and conversion helpers that reproduce C++ semantics exactly.
//!
//! Two pieces of C++ behaviour matter for byte-identical output:
//!
//! * `std::ostream << std::fixed << std::setprecision(n) << double` — glibc
//!   converts the *exact* binary value to decimal and rounds to nearest, ties
//!   to even, which is also what Rust's `{:.n$}` does. Only the non-finite
//!   spellings differ (`nan` / `-nan` / `inf` instead of `NaN` / `inf`), so
//!   those are handled explicitly here.
//! * `static_cast<int>(float)` — on x86-64 this compiles to `cvttss2si`, which
//!   truncates toward zero and yields `INT_MIN` for NaN and for anything
//!   outside the `int` range, rather than saturating the way Rust's `as` does.

/// Formats `value` the way `std::ostream << std::fixed << std::setprecision(precision)` does.
pub fn fixed(value: f64, precision: usize) -> String {
    if value.is_nan() {
        // glibc prints the NaN sign bit; x86 default QNaN (e.g. 0.0f / 0.0f) is negative.
        return if value.is_sign_negative() {
            String::from("-nan")
        } else {
            String::from("nan")
        };
    }
    if value.is_infinite() {
        return if value.is_sign_negative() {
            String::from("-inf")
        } else {
            String::from("inf")
        };
    }
    format!("{:.*}", precision, value)
}

/// Reproduces `static_cast<int>(v)` for a `float` on x86-64 (`cvttss2si`).
pub fn f32_to_i32(v: f32) -> i32 {
    // Anything not representable as an `int` after truncation gives the
    // "integer indefinite" value, INT_MIN.
    if v.is_nan() || v < -2_147_483_648.0_f32 || v >= 2_147_483_648.0_f32 {
        i32::MIN
    } else {
        v as i32
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn fixed_matches_iostream_spelling() {
        assert_eq!(fixed(75.0, 1), "75.0");
        assert_eq!(fixed(0.0, 1), "0.0");
        assert_eq!(fixed(-0.0, 1), "-0.0");
        assert_eq!(fixed(100.0, 1), "100.0");
        assert_eq!(fixed(12.5, 1), "12.5");
        // ties round to even, exactly like glibc's %.1f
        assert_eq!(fixed(0.25, 1), "0.2");
        assert_eq!(fixed(0.75, 1), "0.8");
        assert_eq!(fixed(f64::INFINITY, 1), "inf");
        assert_eq!(fixed(f64::NEG_INFINITY, 1), "-inf");
        assert_eq!(fixed(f64::NAN, 1), "nan");
        assert_eq!(fixed(-f64::NAN, 1), "-nan");
    }

    #[test]
    fn cvttss2si_semantics() {
        assert_eq!(f32_to_i32(22.5), 22);
        assert_eq!(f32_to_i32(-22.5), -22);
        assert_eq!(f32_to_i32(0.0), 0);
        assert_eq!(f32_to_i32(f32::NAN), i32::MIN);
        assert_eq!(f32_to_i32(f32::INFINITY), i32::MIN);
        assert_eq!(f32_to_i32(f32::NEG_INFINITY), i32::MIN);
        assert_eq!(f32_to_i32(1e20), i32::MIN);
        assert_eq!(f32_to_i32(-2_147_483_648.0), i32::MIN);
    }
}

